import sendCustomMail from './sendCustomMail';
import { AccessTo, UserRole } from '../modules/users/user.interface';

type SendAccountApprovedMailPayload = {
  fullName: string;
  email: string;
  role: UserRole;
  accessTo?: AccessTo;
};

const WEBSITE_URL = 'https://we-command-center.vercel.app/';

const getAccessLabel = (accessTo?: AccessTo): string => {
  if (accessTo === 'we_command_center') {
    return 'WÉ Command Center';
  }

  if (accessTo === 'invictus') {
    return 'INVICTUS Academy';
  }

  if (accessTo === 'both') {
    return 'WÉ Command Center + INVICTUS Academy';
  }

  return 'your approved dashboard';
};

export const sendAccountApprovedMail = async ({
  fullName,
  email,
  role,
  accessTo,
}: SendAccountApprovedMailPayload) => {
  const accessLabel = getAccessLabel(accessTo);

  await sendCustomMail({
    to: email,
    subject: 'Your World Elite Account Has Been Approved',

    text: `Hello ${fullName},

Your World Elite account has been approved successfully.

Role: ${role}
Access: ${accessLabel}

You can now log in to your account and access your approved dashboard.

Go to the website:
${WEBSITE_URL}

Thank you,
World Elite Team`,

    html: `
      <div
        style="
          margin: 0;
          padding: 0;
          background-color: #f3f4f6;
          font-family: Arial, Helvetica, sans-serif;
        "
      >
        <div
          style="
            max-width: 600px;
            margin: 0 auto;
            padding: 32px 24px;
          "
        >
          <div
            style="
              background-color: #ffffff;
              padding: 32px;
              border-radius: 12px;
              box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
            "
          >
            <h2
              style="
                margin: 0 0 24px;
                font-size: 24px;
                color: #111827;
                text-align: center;
              "
            >
              Your Account Has Been Approved
            </h2>

            <p
              style="
                font-size: 15px;
                line-height: 1.6;
                color: #374151;
              "
            >
              Hello ${fullName},
            </p>

            <p
              style="
                font-size: 15px;
                line-height: 1.6;
                color: #374151;
              "
            >
              Your World Elite account has been approved successfully.
            </p>

            <div
              style="
                margin: 22px 0;
                padding: 18px;
                background-color: #f3f4f6;
                border-radius: 10px;
              "
            >
              <p
                style="
                  margin: 0 0 8px;
                  color: #111827;
                "
              >
                <strong>Role:</strong> ${role}
              </p>

              <p
                style="
                  margin: 0;
                  color: #111827;
                "
              >
                <strong>Access:</strong> ${accessLabel}
              </p>
            </div>

            <p
              style="
                font-size: 15px;
                line-height: 1.6;
                color: #374151;
              "
            >
              You can now log in to your account and access your approved dashboard.
            </p>

            <div
              style="
                text-align: center;
                margin: 28px 0;
              "
            >
              <a
                href="${WEBSITE_URL}"
                target="_blank"
                rel="noopener noreferrer"
                style="
                  display: inline-block;
                  background-color: #111827;
                  color: #ffffff;
                  padding: 12px 28px;
                  border-radius: 8px;
                  text-decoration: none;
                  font-size: 15px;
                  font-weight: 600;
                "
              >
                Go to Website
              </a>
            </div>

            <p
              style="
                font-size: 13px;
                line-height: 1.6;
                color: #6b7280;
                word-break: break-all;
              "
            >
              Website URL:
              <br />
              <a
                href="${WEBSITE_URL}"
                target="_blank"
                rel="noopener noreferrer"
                style="
                  color: #2563eb;
                  text-decoration: underline;
                "
              >
                ${WEBSITE_URL}
              </a>
            </p>

            <p
              style="
                font-size: 14px;
                line-height: 1.6;
                color: #6b7280;
                margin-top: 25px;
              "
            >
              Thank you,
              <br />
              World Elite Team
            </p>
          </div>
        </div>
      </div>
    `,
  });
};